func Fluxos(mods ...qm.QueryMod) fluxoQuery {
	mods = append(mods, qm.From("`fluxo`"))
	q := NewQuery(mods...)
	if len(queries.GetSelect(q)) == 0 {
		queries.SetSelect(q, []string{"`fluxo`.*"})
	}

	return fluxoQuery{q}
}

// FindFluxo retrieves a single record by ID with an executor.
// If selectCols is empty Find will return all columns.
func FindFluxo(ctx context.Context, exec boil.ContextExecutor, fluID int, selectCols ...string) (*Fluxo, error) {
	fluxoObj := &Fluxo{}

	sel := "*"
	if len(selectCols) > 0 {
		sel = strings.Join(strmangle.IdentQuoteSlice(dialect.LQ, dialect.RQ, selectCols), ",")
	}
	query := fmt.Sprintf(
		"select %s from `fluxo` where `flu_id`=?", sel,
	)

	q := queries.Raw(query, fluID)

	err := q.Bind(ctx, exec, fluxoObj)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, sql.ErrNoRows
		}
		return nil, errors.Wrap(err, "models: unable to select from fluxo")
	}

	if err = fluxoObj.doAfterSelectHooks(ctx, exec); err != nil {
		return fluxoObj, err
	}

	return fluxoObj, nil
}

// Insert a single record using an executor.
// See boil.Columns.InsertColumnSet documentation to understand column list inference for inserts.
func (o *Fluxo) Insert(ctx context.Context, exec boil.ContextExecutor, columns boil.Columns) error {
	if o == nil {
		return errors.New("models: no fluxo provided for insertion")
	}

	var err error

	if err := o.doBeforeInsertHooks(ctx, exec); err != nil {
		return err
	}

	nzDefaults := queries.NonZeroDefaultSet(fluxoColumnsWithDefault, o)

	key := makeCacheKey(columns, nzDefaults)
	fluxoInsertCacheMut.RLock()
	cache, cached := fluxoInsertCache[key]
	fluxoInsertCacheMut.RUnlock()

	if !cached {
		wl, returnColumns := columns.InsertColumnSet(
			fluxoAllColumns,
			fluxoColumnsWithDefault,
			fluxoColumnsWithoutDefault,
			nzDefaults,
		)

		cache.valueMapping, err = queries.BindMapping(fluxoType, fluxoMapping, wl)
		if err != nil {
			return err
		}
		cache.retMapping, err = queries.BindMapping(fluxoType, fluxoMapping, returnColumns)
		if err != nil {
			return err
		}
		if len(wl) != 0 {
			cache.query = fmt.Sprintf("INSERT INTO `fluxo` (`%s`) %%sVALUES (%s)%%s", strings.Join(wl, "`,`"), strmangle.Placeholders(dialect.UseIndexPlaceholders, len(wl), 1, 1))
		} else {
			cache.query = "INSERT INTO `fluxo` () VALUES ()%s%s"
		}

		var queryOutput, queryReturning string

		if len(cache.retMapping) != 0 {
			cache.retQuery = fmt.Sprintf("SELECT `%s` FROM `fluxo` WHERE %s", strings.Join(returnColumns, "`,`"), strmangle.WhereClause("`", "`", 0, fluxoPrimaryKeyColumns))
		}

		cache.query = fmt.Sprintf(cache.query, queryOutput, queryReturning)
	}

	value := reflect.Indirect(reflect.ValueOf(o))
	vals := queries.ValuesFromMapping(value, cache.valueMapping)

	if boil.IsDebug(ctx) {
		writer := boil.DebugWriterFrom(ctx)
		fmt.Fprintln(writer, cache.query)
		fmt.Fprintln(writer, vals)
	}
	_, err = exec.ExecContext(ctx, cache.query, vals...)

	if err != nil {
		return errors.Wrap(err, "models: unable to insert into fluxo")
	}

	var identifierCols []interface{}

	if len(cache.retMapping) == 0 {
		goto CacheNoHooks
	}

	identifierCols = []interface{}{
		o.FluID,
	}

	if boil.IsDebug(ctx) {
		writer := boil.DebugWriterFrom(ctx)
		fmt.Fprintln(writer, cache.retQuery)
		fmt.Fprintln(writer, identifierCols...)
	}
	err = exec.QueryRowContext(ctx, cache.retQuery, identifierCols...).Scan(queries.PtrsFromMapping(value, cache.retMapping)...)
	if err != nil {
		return errors.Wrap(err, "models: unable to populate default values for fluxo")
	}

CacheNoHooks:
	if !cached {
		fluxoInsertCacheMut.Lock()
		fluxoInsertCache[key] = cache
		fluxoInsertCacheMut.Unlock()
	}

	return o.doAfterInsertHooks(ctx, exec)
}

// Update uses an executor to update the Fluxo.
// See boil.Columns.UpdateColumnSet documentation to understand column list inference for updates.
